CREATE SCHEMA IF NOT EXISTS social_private; REVOKE ALL ON SCHEMA social_private FROM PUBLIC, anon; GRANT USAGE ON SCHEMA social_private TO authenticated,service_role; ALTER FUNCTION public.can_use_social_hub(uuid) SET SCHEMA social_private; REVOKE ALL ON FUNCTION social_private.can_use_social_hub(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION social_private.can_use_social_hub(uuid) TO authenticated,service_role;